package main

import (
	"context"
	"fmt"
	"time"
)

// This is a simplified version of what we're testing
type MockConn struct {
	transactionCtx    context.Context
	cancelTransaction func()
}

func (c *MockConn) Begin(ctx context.Context) {
	newCtx, cancel := context.WithCancel(ctx)
	c.transactionCtx = newCtx
	c.cancelTransaction = cancel
}

