	if c.cancelTransaction != nil {
		c.cancelTransaction()
	}
}

func main() {
	conn := &MockConn{}

	// Start a transaction with a background context
	conn.Begin(context.Background())

	// Check if the context is not cancelled yet
	select {
	case <-conn.transactionCtx.Done():
		fmt.Println("ERROR: Context was cancelled prematurely")
		return
	default:
		fmt.Println("OK: Context is not cancelled yet")
	}

	// Close the connection
	conn.Close()

	// Check if the context is now cancelled
	select {
	case <-conn.transactionCtx.Done():
		fmt.Println("OK: Context was cancelled after closing connection")
